  ["a60a4432b367ff3c"] = { "Non promette niente di buono. Mandate degli esploratori a raccogliere altre informazioni, e restate all'erta.", "." },
  ["a6163b47f0666e20"] = { "Tutte le nostre raccolte sono completate, {class}. Ciò che abbiamo riunito è in viaggio verso la ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e l'ultima parte non dovrebbe metterci più di un giorno ad arrivare. Allora potrà iniziare la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧, non appena qualcuno di coraggioso e sconsiderato farà suonare il gong proprio fuori dai cancelli, laggiù.", "." },
  ["a6180a3afc03d027"] = { "Come, non hai un pegno da darmi? Non mi vuoi bene?", "." },
  ["a61ba2574f53deb7"] = { "Notte a tutti. Io non vado ancora a dormire. Magari passa Darcy.", "." },
  ["a622579f8fb0a329"] = { "L'ingegneria ti darà le abilità e le conoscenze per smontare i tuoi avversari! Lascia che ti mostri come...", "." },
  ["a62f01073ffc465e"] = { "Con piacere... lasciami solo assaporare questo momento ancora un minuto.", "." },
  ["a6355b9b0d4c61d2"] = { "%s arrossisce.", "." },
  ["a63a645d6e883743"] = { "Abbassa la voce, straniero. Non vorrai disturbare le meditazioni del Maestro.", "." },
  ["a642f973e2effc3c"] = { "Parla piano e con grande attenzione: da queste parti, una parola sbagliata può costarti la gola tagliata. Allora, cosa ti serve da me?", "." },
  ["a6439ea2e061a8a7"] = { "Grazie, Ironbark. Siamo pronti: puoi aprire la porta.", "." },
  ["a644eb9a667a329c"] = { "Benvenut<o/a> nelle ⟦Stockade=Segrete di Roccavento⟧!", "." },
  ["a652437ed3555874"] = { "Magari non segui le vie della Luce come un Cavaliere della ⟦Silver Hand=Mano d'Argento⟧, ma puoi sempre chiederci aiuto.", "." },
  ["a657df1b12060948"] = { "Grazie a te. Grazie agli sciamani.\n\nCorruzione si ritira ma vita continua a svanire. Tocca a sciamani proteggere vita.", "." },
  ["a663647c46b679fb"] = { "%s guarda a destra e a sinistra...", "." },
  ["a66bec02a6a19bea"] = { "Se non vuoi servire il mio Padrone con la tua spada e con ciò che sai dei suoi nemici...", "." },
  ["a675cae7c0561162"] = { "Il principe ti ha raccontato la storia di Brandicenere? È la nostra preferita tra le sue storie. La sua preferita è il seguito di Brandicenere. Naturalmente, nessuno è mai riuscito a fargliela raccontare.", "." },
  ["a6783cce89df5d8b"] = { "comincia a rallentare!", "." },
  ["a67b40b3e8d3f127"] = { "Ehi, Pratt, puoi insegnarmi di nuovo a fare un ⟦Wild Leather Cloak=Mantello di Cuoio Selvatico⟧?", "." },
  ["a67f6643fdf48b26"] = { "Oggetti abbastanza potenti da aiutarti nel viaggio attraverso ⟦Duskwood=Boscovespro⟧: la merce di Antonio Perelli è ora in vendita qui a ⟦Lakeshire=Borgolago⟧.", "." },
  ["a683163f287ec3f9"] = { "Gli spiriti di ⟦Silithus=Silitus⟧ ci chiamano, {name}. La terra piange, perché ha una storia dolorosa da raccontare...", "." },
  ["a6839b8e26a1395e"] = { "Ah! Ah! Ah! Grazie per la libertà, sciocchi. Ora lasciate che vi ripaghi carbonizzandovi la carne fino alle ossa.", "." },
  ["a689e5935e8b1adb"] = { "Il nostro capitano è caduto!", "." },
  ["a6903032998fc6f0"] = { "Buongiorno, Syurna. Ho bisogno di addestramento.", "." },
  ["a69214795d96f407"] = { "Ora proviamo...", "." },
  ["a693e263508e5b5d"] = { "La presa degli Dei Antichi è inamovibile. Lui è consumato dai loro pensieri oscuri... Io... io non posso... non posso incanalare ancora a lungo... Elune, aiutami...", "." },
  ["a6a2f5bb248e2091"] = { "Sono qui!", "." },
  ["a6a67142966f81b1"] = { "L'Ambasciata dell'⟦Horde=Orda⟧ è nella ⟦Valley of Strength=Valle della Forza⟧, sul lato ovest.", "." },
  ["a6a7e05bd62136d9"] = { "Tilloa, sei tu? Ma no! È solo <un/una> lurid<o/a> {race}!", "." },
  ["a6a7ef1da95339ce"] = { "⟦Zul'Farrak=Zul'farrak⟧ - Weegli Blastfuse - Saluto predefinito.", "." },
  ["a6afae77ff7e31e8"] = { "Salute, viaggiatore. Fu qui, quasi 1.000 anni fa, che i Qiraji cominciarono la loro marcia di distruzione attraverso Kalimdor.\n\nMigliaia di vite andarono perdute durante la guerra, per lo più in questo deserto maledetto, durante l'invasione iniziale.\n\nDi noi ne restano pochi, e io sono tra questi, in catene sia al passato sia al presente. Non so perché devo restare di guardia qui, ma so che devo farlo.", "." },
  ["a6c88e9e8bb44a2a"] = { "Patetico. Il potere del Soulflayer scorre in me. Non temo nulla se non l'ira dell'onnipotente Hakkar. Non servo nessuno se non il mio padrone, Jin.", "." },
  ["a6d637c7dfef399e"] = { "La temperatura è di 564 gradi Kraklenheit.", "." },
  ["a6d7cff8711ddda3"] = { "La terra di Azshara.", "." },
  ["a6d9f1a0f47f9f13"] = { "Quanti cibi cucinati ha raccolto finora l'⟦Horde=Orda⟧?", "." },
  ["a6d9f817740f90d0"] = { "E per le signore, cinghialetto arrosto. Buon appetito!", "." },
  ["a6da29a99600b97e"] = { "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ non sono certo quelle che chiamerei avversarie onorevoli. Ma se sei <deciso/decisa> a massacrarle, {class}, cerca Brakgul Deathbringer nella Hall of the Brave.", "." },
  ["a6da92bacab5a757"] = { "%s armato. Aerie Gryphon in arrivo.", "." },
  ["a6de7b4979389459"] = { "Non profanerai la nostra terra sacra!", "." },
  ["a6e96aa4fcaf24f0"] = { "Se riesci a completare un Mazzo dei Signori della Guerra, riceverai in premio una carta di Lunacupa superiore: la Carta di Lunacupa: Eroismo. Questa carta di tanto in tanto ti curerà mentre combatti in mischia.", "." },
  ["a6f221163056f2b5"] = { "Scommetto che Keryn Sylvius sa che tipo di persona cerchi. La compagnia che frequenta Keryn è tutt'altro che onorevole. Di solito sta al Lion's Pride Inn.", "." },
  ["a6f433da76937dff"] = { "Qui non vengono molti visitatori. Posso interessarti a qualcosa?", "." },
  ["a6f60c772c0c0b49"] = { "È vero che l'⟦Alliance=Alleanza⟧ ha completato tutti i suoi compiti per lo sforzo bellico, ma non lasciarti scoraggiare, {race}. Il tempo stringe, ma preferiamo di gran lunga che tu aiuti nelle raccolte dell'Orda con cura e attenzione. Mi sembra meglio che commettere un errore che potrebbe costare la vita a qualcuno quando questa guerra comincerà davvero. Non sei d'accordo, {class}?", "." },
  ["a6f6f512eb4bfc7f"] = { "Cosa? Perché mi disturbi? Scommetto che non sai nemmeno creare una veste di alta qualità! Va' a parlare con Snang e torna quando sarai <degno/degna> del mio talento!", "." },
  ["a6f77af0c9b13a07"] = { "Dimmi come si usa il Blastenheimer 5000 Ultra Cannon.", "." },
